 jest.mock('next/server', () => ({

const ACCOUNT_DELETION_PATH = '/api/webhooks/ebay/account-deletion';

type RequestEvent = {
  request?: { url?: string };
  transaction?: string;
};

// Sentry's request instrumentation can attach bodies even when the handler
// doesn't read them. Drop both errors and transactions for this endpoint so
// deletion notifications cannot become retained monitoring data.
export function filterEbayAccountDeletionTelemetry<T extends RequestEvent>(event: T): T | null {
  const transactionPath = event.transaction?.replace(/^[A-Z]+\s+/, '');
  for (const value of [event.request?.url, transactionPath]) {
    if (!value) continue;
    try {
      const path = new URL(value, 'https://3dcarparts.org').pathname.replace(/\/$/, '');
      if (path === ACCOUNT_DELETION_PATH) return null;
    } catch {
      // An unrelated malformed URL should not break error reporting.
    }
  }
  return event;
}
